  "/* === TICKETLELO UI FIXES === */\r\n\r\n    /* FAQ section: ensure visibility */\r\n    #faq {\r\n      display: block !important;\r\n      visibility: visible !important;\r\n      opacity: 1 !important;\r\n    }\r\n\r\n    .faq_item {\r\n      display: block !important;\r\n      visibility: visible !important;\r\n    }\r\n\r\n    .faq_header {\r\n      cursor: pointer;\r\n    }\r\n\r\n    /* Ensure sections that may be hidden are shown */\r\n    section.section {\r\n      display: block !important;\r\n    }\r\n\r\n    /* Refined Bar Chart / Column Diagram */\r\n    .column-diagram {\r\n      display: flex;\r\n      flex-direction: row;\r\n      width: 100%;\r\n      gap: 12px;\r\n      margin-top: 24px;\r\n      align-items: flex-end;\r\n    }\r\n\r\n    .column-box {\r\n      display: flex;\r\n      flex-direction: column;\r\n      justify-content: flex-end;\r\n    }\r\n\r\n    /* Proportional flexible widths */\r\n    .column-box:nth-child(1) {\r\n      flex: 6.5;\r\n    }\r\n\r\n    .column-box:nth-child(2) {\r\n      flex: 2.5;\r\n    }\r\n\r\n    .column-box:nth-child(3) {\r\n      flex: 1.0;\r\n      min-width: 60px;\r\n    }\r\n\r\n    /* min-width to fit 10% text */\r\n\r\n    .column-box p {\r\n      margin-top: 0 !important;\r\n      margin-bottom: 12px !important;\r\n      text-align: left;\r\n      padding-left: 8px;\r\n      font-weight: 500;\r\n      white-space: nowrap;\r\n      position: static !important;\r\n      transform: none !important;\r\n    }\r\n\r\n    .column-box .column {\r\n      position: relative;\r\n      height: 70px;\r\n      border-radius: 40px !important;\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      overflow: hidden;\r\n      width: 100%;\r\n    }\r\n\r\n    .column-box .text-size-34 {\r\n      position: absolute !important;\r\n      z-index: 5;\r\n      color: white;\r\n      font-weight: 600;\r\n      margin: 0;\r\n      left: 50%;\r\n      top: 50%;\r\n      transform: translate(-50%, -50%);\r\n    }\r\n\r\n    .progress {\r\n      position: absolute;\r\n      top: 0;\r\n      left: 0;\r\n      height: 100%;\r\n      width: 100%;\r\n      border-radius: 40px !important;\r\n      z-index: 1;\r\n    }\r\n\r\n    @media screen and (max-width: 767px) {\r\n      .column-box .text-size-34 {\r\n        font-size: 20px !important;\r\n      }\r\n\r\n      .column-box p {\r\n        font-size: 11px !important;\r\n        white-space: normal;\r\n        margin-bottom: 6px !important;\r\n      }\r\n    }\r\n\r\n    /* Responsive: mobile cards and layout */\r\n    @media screen and (max-width: 767px) {\r\n      .new-pricing-wrapper {\r\n        flex-direction: column;\r\n      }\r\n\r\n      .content.is--pricing-light {\r\n        width: 100%;\r\n        min-width: 100%;\r\n      }\r\n\r\n      /* Fix pricing tab pills cutting off on mobile */\r\n      .pricing_tabs-menu.cent {\r\n        display: grid !important;\r\n        grid-template-columns: 1fr 1fr;\r\n        gap: 8px;\r\n        padding: 8px !important;\r\n        border-radius: 16px !important;\r\n        /* Fix the broken capsule shape when wrapping */\r\n        height: auto !important;\r\n      }\r\n\r\n      .pricing_tabs-menu.cent .tab-link.o {\r\n        flex: 1 1 auto;\r\n        white-space: normal;\r\n        text-align: center;\r\n        padding: 10px 8px;\r\n        margin: 0 !important;\r\n        border-radius: 12px !important;\r\n        font-size: 14px !important;\r\n        display: flex;\r\n        align-items: center;\r\n        justify-content: center;\r\n      }\r\n\r\n      /* Ensure navbar timer stacks correctly and is visible on small screens */\r\n      .timeline-wrapper {\r\n        flex-direction: column !important;\r\n        align-items: center !important;\r\n        text-align: center !important;\r\n        padding: 10px 0;\r\n        gap: 8px;\r\n      }\r\n\r\n      .sale-style .timer {\r\n        margin-right: 0 !important;\r\n        justify-content: center !important;\r\n        width: 100%;\r\n      }\r\n\r\n      .timeline-wrapper p {\r\n        margin-left: 0 !important;\r\n        font-size: 14px !important;\r\n      }\r\n    }\r\n\r\n    /* Cards: make them fill their container and be responsive */\r\n    .content.community-small {\r\n      min-height: 140px;\r\n      box-sizing: border-box;\r\n      width: 100%;\r\n    }\r\n\r\n    .new-pricing-wrapper {\r\n      display: flex;\r\n      flex-wrap: wrap;\r\n      gap: 20px;\r\n    }\r\n\r\n    .content.is--pricing-light {\r\n      flex: 1 1 0%;\r\n      min-width: 280px;\r\n      box-sizing: border-box;\r\n      height: auto !important;\r\n      min-height: max-content !important;\r\n      padding-bottom: 32px !important;\r\n    }\r\n\r\n    /* Ensure tab content wrappers stretch to fit the new lists */\r\n    .tabs-content-2,\r\n    .w-tab-content,\r\n    .w-tab-pane {\r\n      height: auto !important;\r\n      overflow: visible !important;\r\n    }\r\n\r\n    /* Responsive: mobile cards */\r\n    @media screen and (max-width: 767px) {\r\n      .new-pricing-wrapper {\r\n        flex-direction: column;\r\n      }\r\n\r\n      .content.is--pricing-light {\r\n        flex: 1 1 100%;\r\n        min-width: unset;\r\n        width: 100%;\r\n      }\r\n\r\n      .content.community-small {\r\n        min-height: 120px;\r\n      }\r\n\r\n      ._4-col-grid {\r\n        display: grid !important;\r\n        grid-template-columns: 1fr 1fr !important;\r\n        gap: 16px !important;\r\n      }\r\n    }\r\n\r\n    @media screen and (max-width: 479px) {\r\n      ._4-col-grid {\r\n        grid-template-columns: 1fr !important;\r\n      }\r\n    }\r\n\r\n    /* Timer: ensure always visible when .sale-style is shown */\r\n    .sale-style .timer {\r\n      display: flex !important;\r\n      align-items: center;\r\n      gap: 4px;\r\n      margin-right: 16px;\r\n    }\r\n\r\n    .timeline-wrapper p {\r\n      margin-left: 12px;\r\n      font-size: 1.1em;\r\n    }\r\n\r\n    .timer__days,\r\n    .timer__hours,\r\n    .timer__minutes,\r\n    .timer__seconds {\r\n      display: inline-block;\r\n      min-width: 2ch;\r\n      font-variant-numeric: tabular-nums;\r\n    }\r\n\r\n    /* === PRICING TAB ALIGNMENT FIX ===\r\n       Webflow's w--current adds a large white bubble via box-shadow/transform.\r\n       Reset it to a flat, clean pill highlight. */\r\n    .pricing_tabs-menu.cent .tab-link.o {\r\n      position: relative;\r\n      z-index: 1;\r\n      border-radius: 50px;\r\n      padding: 10px 18px;\r\n      font-size: inherit;\r\n      text-align: center;\r\n      transition: background 0.2s ease, color 0.2s ease;\r\n      /* Prevent Webflow from stretching the active pill */\r\n      flex: 1 1 auto;\r\n      white-space: nowrap;\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      min-height: 44px;\r\n    }\r\n\r\n    .pricing_tabs-menu.cent .tab-link.o.w--current {\r\n      background: white !important;\r\n      color: #0b1a57 !important;\r\n      box-shadow: none !important;\r\n      transform: none !important;\r\n      border-radius: 50px !important;\r\n      /* Prevent the giant bubble */\r\n      width: auto !important;\r\n      height: auto !important;\r\n      padding: 10px 18px !important;\r\n      margin: 4px !important;\r\n    }\r\n\r\n    /* Ensure the tab menu itself is a stable pill container */\r\n    .pricing_tabs-menu.cent {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: space-between;\r\n      padding: 4px;\r\n      border-radius: 50px;\r\n      gap: 2px;\r\n      flex-wrap: nowrap;\r\n      overflow: hidden;\r\n    }\r\n\r\n    /* Preloader counter */\r\n    .count-wrapper {\r\n      display: flex;\r\n      align-items: baseline;\r\n      gap: 2px;\r\n    }\r\n\r\n    #preloader-count {\r\n      font-variant-numeric: tabular-nums;\r\n      min-width: 3ch;\r\n      display: inline-block;\r\n    }",
